<script setup>
import { Link, router } from '@inertiajs/vue3';
import { ref } from 'vue';
import AssessmentLayout from './AssessmentLayout.vue';
const props = defineProps({ quest:Object, submissions:Object, filters:Object, downloadableFilesCount:Number });
const search = ref(props.filters?.search || ''); const status = ref(props.filters?.status || 'all');
const apply = () => router.get(route('redesign.quests.submissions',props.quest.uuid),{search:search.value || undefined,status:status.value},{preserveState:true,replace:true});
</script>
<template><AssessmentLayout title="Submission per quest" :subtitle="quest.title"><template #action><a v-if="downloadableFilesCount" class="primary" :href="route('admin.quests.submissions.download-files',{quest:quest.uuid,search:filters?.search,status:filters?.status})">Unduh semua file</a></template><div class="tabs"><Link :class="{active:filters?.status==='all'}" :href="route('redesign.quests.submissions',quest.uuid)">Semua</Link><Link :class="{active:filters?.status==='Pending'}" :href="route('redesign.quests.submissions',{quest:quest.uuid,status:'Pending'})">Menunggu</Link></div><form class="filters" @submit.prevent="apply"><input v-model="search" aria-label="Cari peserta" placeholder="Cari nama peserta..." /><select v-model="status" aria-label="Status"><option value="all">Semua status</option><option value="Pending">Menunggu</option><option value="Approved">Disetujui</option><option value="Rejected">Ditolak</option></select><button class="action">Filter</button><Link class="secondary" :href="route('redesign.quests.submissions',quest.uuid)">Reset</Link></form><section class="panel"><h2>Submission per quest</h2><div class="table-wrap"><table><thead><tr><th>Peserta</th><th>Status</th><th>Nilai</th><th>Dikirim pada</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in submissions?.data || []" :key="item.uuid"><td><strong>{{ item.user?.name || item.user?.username || 'Peserta' }}</strong></td><td>{{ item.status }}</td><td>{{ item.grade ?? '—' }}</td><td>{{ item.created_at ? new Date(item.created_at).toLocaleString('id-ID') : '—' }}</td><td><Link :href="route('redesign.submissions.inspect',item.uuid)">Inspect</Link></td></tr><tr v-if="!submissions?.data?.length"><td colspan="5" class="muted">Belum ada submission.</td></tr></tbody></table></div><div class="pager"><Link v-for="(link,i) in submissions?.links || []" :key="i" :href="link.url || '#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label" /></div></section></AssessmentLayout></template>
